namespace eval implement_flow {
    variable flow_id [flng::get_next_available_id -type flow]
    variable flow [flng::add_object -type flow_definition -number $flow_id -name implement]
    flng::set_property -object $flow -name identifier -value "Implement"
    flng::set_property -object $flow -name description -value "Run Compilation from start to Fitter Route or Retime"
    flng::set_property -object $flow -name storage_engine -value "qhd"

    variable ipgen [flng::get_objects -type task_definition -name "ipgenerate"]
    if {$ipgen == ""} {
        error "Error: unable to find ipgenerate task"
    } else {
        lappend task_list $ipgen
    }

    variable quick_elab [flng::get_objects -type task_definition -name "quick_elab"]
    if {$quick_elab == ""} {
        error "Error: unable to find Quick Elaborate task"
    } else {
        lappend task_list $quick_elab
    }

    variable qtlg [flng::get_objects -type task_definition -name "tlg"]
    if {$qtlg == ""} {
        error "Error: unable to find Plan Interface task"
    } else {
        lappend task_list $qtlg
    }

    variable qsyn [flng::get_objects -type task_definition -name "synthesis"]
    if {$qsyn == ""} {
        error "Error: unable to find synthesis task"
    } else {
        lappend task_list $qsyn
    }


    variable fit_plan [flng::get_objects -type task_definition -name "fitter_plan"]
    if {$fit_plan == ""} {
        error "Error: unable to find fit_plan task."
    } else {
        lappend task_list $fit_plan
    }

    variable fit_place [flng::get_objects -type task_definition -name "fitter_place"]
    if {$fit_place == ""} {
        error "Error: unable to find fit_place task."
    } else {
        lappend task_list $fit_place
    }

    variable fit_route [flng::get_objects -type task_definition -name "fitter_route"]
    if {$fit_route == ""} {
        error "Error: unable to find fit_route task."
    } else {
        lappend task_list $fit_route
    }

    variable fit_retime [flng::get_objects -type task_definition -name "fitter_retime"]
    if {$fit_retime == ""} {
        error "Error: unable to find fit_retime task."
    } else {
        lappend task_list $fit_retime
    }

    variable qsta [flng::get_objects -type task_definition -name "sta_implement"]
    if {$qsta == ""} {
        error "Error: unable to find sta_implement task"
    } else {
        lappend task_list $qsta
    }


    flng::set_property -object $flow -name tasks -value $task_list

    flng::add_property -object $flow -name depends_on:$ipgen -value $quick_elab
    flng::add_property -object $flow -name depends_on:$quick_elab -value $qtlg
    flng::add_property -object $flow -name depends_on:$qtlg -value $qsyn
    flng::add_property -object $flow -name depends_on:$qsyn -value [list $fit_plan]    
    flng::add_property -object $flow -name depends_on:$fit_plan -value [list $fit_place]
    flng::add_property -object $flow -name depends_on:$fit_place -value [list $fit_route]
    flng::add_property -object $flow -name depends_on:$fit_route -value [list $fit_retime $qsta]
    flng::add_property -object $flow -name depends_on:$fit_retime -value [list $qsta]



	flng::add_property -object $flow -name parameters:rapid_recompile -value ""
}

