        variable fit_plan [flng::get_objects -type task_definition -name "fitter_plan"]
        variable fitter [flng::get_objects -type task_definition -name "fitter"]
        if {[string compare -nocase $use_split_fitter "on"] == 0} {
            return $fit_plan
        } else {
            # Check if the start or end task id are specified.
            # If specified and they land on the split fitter branch, split fitter 
            # will be used.
            #
            if {$start_task ne "" || $end_task ne ""} {
                variable split_tasks [list]
                lappend split_tasks "task_definition:fitter_plan"
                lappend split_tasks "task_definition:fitter_place"
                lappend split_tasks "task_definition:fitter_route"
                lappend split_tasks "task_definition:fitter_retime"
                lappend split_tasks "task_definition:fitter_fastforward_timing"
                lappend split_tasks "task_definition:fitter_finalize"
                if {$start_task ne ""} {
                    variable start_in_branch [lsearch $split_tasks $start_task]
                    if {$start_in_branch != -1} {
                        return $fit_plan
                    }
                }
                if {$end_task ne ""} {
                    variable end_in_branch [lsearch $split_tasks $end_task] 
                    if {$end_in_branch != -1} {
                        return $fit_plan
                    }
                }
                return $fitter 
            } else {
                return $fitter
            }
        }
    }
}

