namespace eval pcc_add_dynamic_to_flow_task {
    variable id [flng::get_next_available_id -type task_definition]
    variable task1 [flng::add_object -type task_definition -number $id -name "pcc_add_dynamic_to_flow_task"]
    flng::set_property -object $task1 -name smart_action -value "DONE"
    flng::set_property -object $task1 -name identifier -value "Generate PCC IP tasks"
    flng::set_property -object $task1 -name description -value "Creating techmap synthesis tasks for PCC IPs"
    flng::set_property -object $task1 -name storage_engine -value qhd

    # This tcl func is evaluated in GUI process.  There may be other error messages.
    # Use only  error_count in this OCS namespace and only post message using this 
    # namespace's post_error instead of post_message -type error directly 
    #
    variable error_count 0
    proc post_error { msg } {
        variable error_count
        post_message -type error $msg
        incr error_count 1
    }

    proc create_task { ip_proj flow_id } {

        set numeric_id [flng::get_next_available_id -type task] 
        set new_task [flng::add_object -type task -number $numeric_id -name $ip_proj]
        flng::set_property -object $new_task -name task -value "task_definition:pcc_ip_syn_export_task"
        # ip_proj is in the form <ip name>|<ip library>|syn_export.
        flng::set_property -object $new_task -name identifier -value "${ip_proj}"
        flng::set_property -object $new_task -name flow -value $flow_id

        return $new_task
    }

    proc delete_previous_dynamic_tasks {flow_id creator_task_id} {
        msg_vdebug "Delete tasks generated in last compilation: $flow_id, $creator_task_id"
        set tasks [flng::get_property -object $flow_id -name tasks]
        set new_task_list [list]

        foreach task $tasks {
            set created_by [flng::get_property -object $task -name dynamically_generated_by]
            if {$creator_task_id eq $created_by} {
                flng::delete_object -object $task
            } else {
                lappend new_task_list $task
            }
        }
        flng::set_property -object $flow_id -name tasks -value $new_task_list
    }

    proc get_ip_cache_dir { } {
        set home_dir [pwd]
        foreach_in_collection asgn [get_all_global_assignments -name "OCS_CACHE_DIRECTORY"] {
            set ip_cache_dir [lindex $asgn 2]
            msg_vdebug "Retrieved the OCS_CACHE_DIRECTORY value: $ip_cache_dir"
            set ip_cache_dir [file join $home_dir $ip_cache_dir]
            msg_vdebug "Using absolute path for OCS_CACHE_DIRECTORY: $ip_cache_dir"
            return $ip_cache_dir
        }
        post_error "A default value for OCS_CACHE_DIRECTORY was not set."
        return ""
    }

    # task function 
    proc get_ip_file_asgns { task_id } {

        variable error_count 0
        package require ::quartus::dni_ocs

        set task_def [flng::get_property -object $task_id -name task]
        set identifier [flng::get_property -object $task_def -name identifier]
        write_flow_started -flow_name $identifier 
        write_flow_assignment_digest -flow_name $identifier

        set ip_list {}
        set pcc_beta_mode [get_ini_var -name "pcc_beta_mode"]
        if { [string equal -nocase "OFF" $pcc_beta_mode] } {
            foreach_in_collection asgn_id [get_all_assignments -name "OCS_IP_TYPE" -type global] {
                set component [get_assignment_info $asgn_id -value]
                if { [dni::is_pcc_ip -component $component] } {
                    set entity [get_assignment_info $asgn_id -entity]
                    set library [get_assignment_info $asgn_id -library]
                    lappend ip_list $entity $library
                }
            }
        } else {
            foreach_in_collection asgn_id [get_all_assignments -name "PRE_COMPILED_MODULE" -type global] {
                set asgn_value [get_assignment_info $asgn_id -value]
                if { [string equal -nocase "ON" $asgn_value] } {
                    set entity [get_assignment_info $asgn_id -entity]
                    set library [get_assignment_info $asgn_id -library]
                    lappend ip_list $entity $library
                }
            }
        }

        set flow_id [flng::get_property -object $task_id -name flow]
        delete_previous_dynamic_tasks $flow_id $task_id


        msg_vdebug "Adding task to flow $flow_id"

        if { [ catch { dni::open_ocs_cache } err ] } {
            post_error "Unable to open the IP cache db: $err"    
        }
        set ip_root_cache_dir [get_ip_cache_dir]
        set ip_full_cache_dir [file join $ip_root_cache_dir [dni::get_ocs_cache_sub_dir]]

        set flow_tasks [flng::get_property -object $flow_id -name tasks]
        set new_tasks []
        set processed_entries []
        # Sort the list to ensure parity when recreating this list elsewhere
        # TODO: centralize this process
        set ip_list [lsort -stride 2 $ip_list]
        foreach {ip_entity ip_library} $ip_list {
            set status [dni::read_ocs_ip_entry -entity $ip_entity -library $ip_library -field "status"]
            if {$status eq "skip"} {
                msg_vdebug "Entity $ip_entity from library $ip_library has been marked to be skipped for Precompiled Component Generation. Skipping generation for this entity."
                continue
            }

            set local_cache [dni::get_local_cache]
            if { [dni::ip_cache_contains_ip -entity $ip_entity -library $ip_library -cache $local_cache] } {
                set qdb_file_path [dni::get_ocs_ip_entry_qdb_file -entity $ip_entity -library $ip_library]
                # NOTE: the following info message is found in prev files for PCC regtests
                post_message -type info "An IP cache entry has already been successfully generated for entity $ip_entity from library $ip_library at $qdb_file_path. Skipping generation for this entity."
                continue
            }

            # In entity-agnostic caching, all IP entities of the same type and parameterization will map to
            # the same cache entry. Keep track of already processed entries so we only synthesize and cache
            # one instance
            set entry_name [dni::get_ocs_ip_cache_entry_name -entity $ip_entity -library $ip_library]
            if { [lsearch -exact $processed_entries $entry_name] >= 0 } {
                continue
            }
            lappend processed_entries $entry_name

            # NOTE: We're not setting the revision in these commands because we know it's the same as the project.
            # TODO: consider adding the concept of a pwd to the flow engine so we can pop on/off the dirs where pcc projects are compiled
            set new_syn_worker_task [create_task "${ip_entity}|${ip_library}|syn_export" $flow_id ]
            flng::add_property -object $new_syn_worker_task -name parameters:ip_entity -value $ip_entity
            flng::add_property -object $new_syn_worker_task -name parameters:ip_library -value $ip_library
            flng::set_property -object $new_syn_worker_task -name dynamically_generated_by -value $task_id

            # Record the directory the ip will be synthesized to enable main project to import this IP's compile progress.	
	        set ip_dir [file join $ip_full_cache_dir "$entry_name"]
            flng::set_property -object $new_syn_worker_task -name import_status_from_project -value $ip_dir
            flng::set_property -object $new_syn_worker_task -name import_status_from_tasks -value [list "Analysis & Elaboration" "Synthesis"]

            lappend new_tasks $new_syn_worker_task  
            lappend flow_tasks $new_syn_worker_task  
        }

        # TODO: This update should set a flag for the GUI to refresh the task list.
        flng::set_property -object $flow_id -name tasks -value $flow_tasks

        # Add to run queue after the flow is setup. It needs flow graph to reset status.
        foreach new_syn_worker_task $new_tasks {
            flng::add_task_to_run_queue -task_id $new_syn_worker_task
        }

        set success [expr {$error_count == 0}]
        set critical_warnings 0 
        write_flow_finished -flow_name $identifier -success $success -errors $error_count -critical_warnings $critical_warnings 
        post_message -type info "Finish writing flow finished: $identifier"

        return 1
    }
    flng::set_property -object $task1 -name tcl_command_template -value "pcc_add_dynamic_to_flow_task::get_ip_file_asgns"
}

